                                &info.derivation_alg, NULL, 0);
        sc_format_asn1_entry(asn1_pbes2_params + 1,
                                &info.key_encr_alg, NULL, 0);
        memset(&info, 0, sizeof(info));

        r = _sc_asn1_decode(ctx, asn1_pbes2_params, buf, buflen, NULL, NULL, 0, depth + 1);
        if (r < 0)
                return r;
